namespace sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Description,
    string Location);

using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Models;

namespace sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Models;
using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Services;

namespace sv_4c577edd0b5a402d8aaa42b8719dfc77.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            DateTimeOffset.UtcNow.AddDays(2),
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-3), "Package picked up", "New York, NY"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-2), "Departed facility", "New York, NY"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-1), "Arrived at sorting center", "Chicago, IL"),
            ]),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            DateTimeOffset.UtcNow.AddDays(-1),
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-5), "Package picked up", "Seattle, WA"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-4), "In transit", "Portland, OR"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-2), "Out for delivery", "San Francisco, CA"),
                new StatusUpdate(DateTimeOffset.UtcNow.AddDays(-1), "Delivered", "San Francisco, CA"),
            ]),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Dallas, TX",
            DateTimeOffset.UtcNow.AddDays(5),
            [
                new StatusUpdate(DateTimeOffset.UtcNow.AddHours(-6), "Label created", "Dallas, TX"),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net;
using System.Net.Http.Json;
using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Models;

namespace sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Services;

/// <summary>
/// Calls the server API when running in WebAssembly.
/// </summary>
public sealed class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Models
@using sv_4c577edd0b5a402d8aaa42b8719dfc77.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>

    <dl class="row">
        <dt class="col-sm-3">Status</dt>
        <dd class="col-sm-9">@_shipment.Status</dd>

        <dt class="col-sm-3">Location</dt>
        <dd class="col-sm-9">@_shipment.Location</dd>

        <dt class="col-sm-3">Estimated Delivery</dt>
        <dd class="col-sm-9">@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h4>Tracking History</h4>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string? _lastTrackingNumber;

    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_lastTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
            return;

        _lastTrackingNumber = TrackingNumber;
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        CancelPending();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — stop silently.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

